var a=`0688-cassava-leaf-stew`;var s=`world-0688`;var i=`SL`;var n=`western-africa`;var r=4;var o=76;var l={en:`Cassava Leaf Stew`,ua:`Рагу з листя маніоку`};var u={en:`Cassava Leaf Stew is a Sierra Leone classic prepared with yellow onion, tomato, beef chuck, peanut butter. A measured home-style version, with ingredients assigned to the cooking steps where they are used. This is a spinach-based adaptation, NOT cassava-leaf stew: fresh cassava leaves are missing and require special detoxification. Never substitute untreated leaves.`,ua:`Рагу з листя маніоку, страва кухні країни Сьєрра-Леоне зі складниками: жовта цибуля, помідор, яловича лопатка, арахісова паста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Це варіант зі шпинатом, а НЕ рагу з листя маніоку: потрібного листя немає, а сире листя вимагає спеціального знешкодження. Не використовуйте необроблене.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`red-palm-oil`,65,`ml`],[`tomato`,230,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 48 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 48 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:48,i:[[`beef-chuck`,550,`g`],[`water`,750,`ml`],[`peanut-butter`,160,`g`],[`crayfish`,115,`g`]]},{en:`Cook the spinach fully in the nutty stew for the final 15 minutes. This variation intentionally uses NO cassava leaves.`,ua:`Повністю приготуйте шпинат в арахісовій підливі протягом останніх 15 хвилин. У цьому варіанті листя маніоку НЕ використовується.`,t:[`stewing`],m:15,i:[[`spinach`,400,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`]]}];var d={slug:a,id:s,country:`SL`,region:n,servings:4,minutes:76,title:l,text:u,steps:h};export{i as country,d as default,s as id,o as minutes,n as region,r as servings,a as slug,h as steps,u as text,l as title};